<title>Titan Hub</title><style>html,body{margin:0;background:#000;color:#fff;font-family:system-ui,sans-serif}*{box-sizing:border-box}.shell{min-height:100dvh;display:grid;grid-template-rows:1fr auto}.main{padding:20px;max-width:900px;width:100%;margin:auto}.card{border:1px solid #252525;border-radius:18px;padding:18px;background:#090909}.nav{position:sticky;bottom:0;display:grid;grid-template-columns:repeat(4,1fr);gap:4px;background:#000;border-top:1px solid #222;padding:8px max(8px,env(safe-area-inset-right)) max(8px,env(safe-area-inset-bottom)) max(8px,env(safe-area-inset-left))}.nav button{background:#090909;color:#fff;border:1px solid #222;border-radius:14px;padding:12px}.nav button[aria-current=true]{border-color:#0055ff}.muted{color:#aaa}.summary-banner{padding:4px 2px 16px}.summary-title{font-size:1.6rem;margin:.2rem 0}.data-list{display:grid;gap:10px}.entity-card{border:1px solid #222;border-radius:14px;padding:14px;background:#050505}.entity-title{margin:0 0 10px}.entity-row,.kv-row{display:flex;justify-content:space-between;gap:14px;padding:7px 0;border-top:1px solid #171717}.entity-key,.kv-key{text-transform:capitalize;color:#aaa}.action-bar{display:flex;gap:8px;padding:14px 0}.action-button{background:#0055ff;color:#fff;border:0;border-radius:12px;padding:12px 16px;font-weight:650}.chat-message{border-top:1px solid #1d1d1d;padding:12px 0}.network-status{font-size:.8rem;font-weight:650;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px}.connectivity{position:fixed;top:max(8px,env(safe-area-inset-top));right:10px;z-index:3;font-size:.72rem;background:#090909;border:1px solid #222;border-radius:999px;padding:5px 9px}.connectivity[data-state=offline]{border-color:#f59e0b}</style>
</head><body><div id="hub-connectivity" class="connectivity" data-state="online" aria-live="polite">Online</div><div class="shell"><main id="hub-main" class="main"><section class="card"><h1>Titan Hub</h1><p class="muted">Loading your customer workspace…</p></section></main><nav class="nav" aria-label="Titan Hub"><button data-workspace="home" aria-current="true">Home</button><button data-workspace="book">Book</button><button data-workspace="inbox">Inbox</button><button data-workspace="more">More</button></nav></div>
